const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');
return [{ json: { requesterId: parseInt(match[1], 10) } }];

const requester = $input.first().json;
const body = $('Webhook - Test Stage Reminder Step').first().json.body || {};

if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (requester.role !== 'admin') throw new Error('Admin access required.');

const testEmail = (body.test_email || '').toString().trim();
const subject = (body.email_subject || '').toString().trim();
const emailBody = (body.email_body || '').toString();

if (!testEmail) throw new Error('"test_email" is required.');
if (!subject) throw new Error('"email_subject" is required.');
if (!emailBody.trim()) throw new Error('"email_body" is required.');

const sampleDate = new Date(Date.now() + 24 * 3600000).toLocaleString('en-US', { dateStyle: 'full', timeStyle: 'short' });

function fill(template) {
  return template
    .replace(/{{\s*first_name\s*}}/gi, 'Test')
    .replace(/{{\s*last_name\s*}}/gi, 'Contact')
    .replace(/{{\s*deal_name\s*}}/gi, 'Sample Deal')
    .replace(/{{\s*appointment_date\s*}}/gi, sampleDate);
}

return [{ json: { testEmail, subject: '[TEST] ' + fill(subject), body: fill(emailBody) } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

const body = $input.first().json.body || {};
const ruleId = parseInt(body.rule_id, 10);
if (!Number.isInteger(ruleId)) throw new Error('"rule_id" must be an integer.');

return [{ json: { requesterId: parseInt(match[1], 10), ruleId } }];

const requester = $input.first().json;
if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (requester.role !== 'admin') throw new Error('Admin access required.');
return [{ json: { ruleId: $('Parse Token & Payload (Force)').item.json.ruleId } }];

const row = $input.item.json;

function fill(template) {
  const apptDate = new Date(row.due_at).toLocaleString('en-US', { dateStyle: 'full', timeStyle: 'short' });
  return (template || '')
    .replace(/{{\s*first_name\s*}}/gi, row.first_name || 'there')
    .replace(/{{\s*last_name\s*}}/gi, row.last_name || '')
    .replace(/{{\s*appointment_date\s*}}/gi, apptDate)
    .replace(/{{\s*deal_name\s*}}/gi, row.opportunity_name || '');
}

return [{
  json: {
    stepId: row.step_id,
    opportunityId: row.opportunity_id,
    activityId: row.activity_id,
    to: row.email,
    subject: fill(row.email_subject),
    body: fill(row.email_body),
  },
}];

const row = $input.item.json;

function fill(template) {
  return (template || '')
    .replace(/{{\s*first_name\s*}}/gi, row.first_name || 'there')
    .replace(/{{\s*last_name\s*}}/gi, row.last_name || '')
    .replace(/{{\s*deal_name\s*}}/gi, row.opportunity_name || '');
}

return [{
  json: {
    hasEmail: !!(row.on_complete_email_subject && row.on_complete_email_subject.trim()),
    to: row.email,
    subject: fill(row.on_complete_email_subject),
    body: fill(row.on_complete_email_body),
    onCompleteAdvanceStageId: row.on_complete_advance_stage_id,
    opportunityId: row.opportunity_id,
    ruleId: row.rule_id,
    activityId: row.activity_id,
    contactId: row.contact_id,
  },
}];
